/* Lot 101: the reader colour (wf_cssprop_color): lab(), lch(), oklab(), oklch(), color() (generated by scripts/lot101_colorgen.py; expectations from scripts/lot101_colormodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static wf_cssprop_t g_p;
static char g_o[160];

static int syn(const char *s) {
    memset(&g_p, 0, sizeof(g_p));
    g_p.syntax = (unsigned char)wf_cssprop_syntax_parse(s, (int)strlen(s), &g_p);
    return g_p.syntax != 0;
}

/* the reader colour of v[0..n) as "#rrggbb alpha", "-" when it is not one */
static const char *rcn(const char *v, int n) {
    unsigned int c = 0xdeadbeefu;
    int a = -7, r = wf_cssprop_color(v, n, &c, &a);
    if (!r) return c == 0xdeadbeefu && a == -7 ? "-" : "WRITTEN";
    if (r != 1 || c > 0xffffffu || a < 0 || a > 255) return "BAD CODE";
    snprintf(g_o, sizeof(g_o), "#%06x %d", c, a);
    return g_o;
}

static const char *rc(const char *v) { return rcn(v, (int)strlen(v)); }

static void test_l101_color_0(void) {
    TEST_ASSERT_EQUAL_STRING("#777777 255", rc("lab(50 0 0)"));
    TEST_ASSERT_EQUAL_STRING("#ffffff 255", rc("lab(100 0 0)"));
    TEST_ASSERT_EQUAL_STRING("#000000 255", rc("lab(0 0 0)"));
    TEST_ASSERT_EQUAL_STRING("#777777 255", rc("lch(50 0 0)"));
    TEST_ASSERT_EQUAL_STRING("#ffffff 255", rc("oklab(1 0 0)"));
    TEST_ASSERT_EQUAL_STRING("#000000 255", rc("oklab(0 0 0)"));
    TEST_ASSERT_EQUAL_STRING("#96a85e 255", rc("oklch(0.7 0.1 120)"));
    TEST_ASSERT_EQUAL_STRING("#ff0000 255", rc("lab(54.29 80.82 69.88)"));
    TEST_ASSERT_EQUAL_STRING("#ff0000 255", rc("oklab(0.62796 0.22486 0.12585)"));
    TEST_ASSERT_EQUAL_STRING("#ff0000 255", rc("color(srgb 1 0 0)"));
    TEST_ASSERT_EQUAL_STRING("#bcbcbc 255", rc("color(srgb-linear 0.5 0.5 0.5)"));
    TEST_ASSERT_EQUAL_STRING("#ff0000 255", rc("color(display-p3 1 0 0)"));
}

